html=java.ajax(su),
token=org.jsoup.Jsoup.parse(html)
.select('input[name=_token]')
.attr('value');
so=su+"/search,"
body=`keyword=${key}&page={{page}}&_token=${token}`;
post=JSON.stringify({
  "body": String(body),
  "method": "POST"
});

so+post

